 <label>เมนูแทน<select data-testid="replacement-menu" data-item-id="${i.id}"><option value="">เลือกเมนูแทน</option>${s.menus.map(m=>`<option value="${esc(m.id)}" ${m.id===d?.menuId?'selected':''} ${menuAvailable(m)?'':'disabled'}>${esc(m.name)} · ${money(m.price)} ${menuAvailable(m)?'':'หมด / ปิดขาย'}</option>`).join('')}</select></label>
